"""直接运行的 FinQA 证据回归检查：只查询 SQLite，不调用模型。"""

import os
from pathlib import Path
import sys

PROJECT_ROOT = Path(__file__).resolve().parents[1]
os.chdir(PROJECT_ROOT)
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from app.tools.retrieval import find_finqa_reports, get_financial_report  # noqa: E402


def main() -> None:
    metrics = [
        "property plant and equipment net",
        "cash generated by operating activities",
        "long-term debt",
    ]
    located = find_finqa_reports.invoke({
        "company": "Apple",
        "year": 2014,
        "metrics": metrics,
        "query": "Apple 2014 financial report 2013 comparatives",
    })
    assert located["found"], located
    first = located["results"][0]
    assert first["report_id"].startswith("AAPL/2014/page_38.pdf-")
    assert set(first["matched_metrics"]) == set(metrics)
    assert not first["unmatched_metrics"]
    assert located["distinct_candidates"] < located["total_candidates"]
    assert len(first["source_refs"]) > 1
    print("第一候选：", first["report_id"], first["split"])
    print("匹配指标：", first["matched_metrics"])
    print("候选数：", located["total_candidates"], "去重后：", located["distinct_candidates"])
    print("合并来源：", first["source_refs"])

    evidence = get_financial_report.invoke({
        "report_id": first["report_id"],
        "metrics": metrics,
    })
    assert evidence["found"], evidence
    assert "stop_retrieval" not in evidence
    rows = evidence["table_rows"]
    assert rows[0] == ["", "2014", "2013", "2012"]
    values = {row[0]: row[1:] for row in rows}
    assert values["property plant and equipment net"][:2] == ["$ 20624", "$ 16597"]
    assert values["cash generated by operating activities"][:2] == ["$ 59713", "$ 53666"]
    assert values["long-term debt"][:2] == ["$ 28987", "$ 16960"]
    assert any("in millions" in text.lower() for text in evidence["context_snippets"])
    print("六个原始数值、年份表头及百万美元单位检查通过。")

    aliases = get_financial_report.invoke({
        "report_id": first["report_id"],
        "metrics": ["固定资产净额", "net cash provided by operating activities", "长期债务"],
    })
    assert len(aliases["matched_metrics"]) == 3
    assert not aliases["unmatched_metrics"]
    print("中文及英文受控别名检查通过。")

    partial = get_financial_report.invoke({
        "report_id": first["report_id"],
        "metrics": ["long-term debt", "不存在的测试指标", "debt"],
    })
    assert partial["found"]
    assert partial["matched_metrics"] == ["long-term debt"]
    assert partial["unmatched_metrics"] == ["不存在的测试指标", "debt"]
    assert partial["metric_match_scope"] == "current_report_table_row_labels"
    print("当前报告部分匹配与宽泛词误匹配检查通过。")
    print("第三步检查全部通过。")


if __name__ == "__main__":
    main()
